#!/usr/bin/env python3
"""Gera uma central HTML pessoal, fora do Git, a partir dos Markdown do projeto."""
from pathlib import Path
import json,re
root=Path(__file__).resolve().parent.parent
excluded={'node_modules','artifacts','teste','.git','.codex','.agents'}
docs=[]
for p in sorted(root.rglob('*.md')):
    if any(part in excluded for part in p.relative_to(root).parts):continue
    text=p.read_text()
    title=next((line.lstrip('# ').strip() for line in text.splitlines() if line.startswith('# ')),p.stem)
    rel=p.relative_to(root).as_posix()
    group='Operação e implantação' if rel.startswith('deploy/') or p.name=='LOCAWEB.md' else 'API e banco' if rel.startswith(('apis/','database/')) else 'Produto e planejamento' if p.parent==root or 'PLANEJAMENTO' in p.name else 'Validações e referências'
    docs.append({'id':rel,'title':title,'group':group,'text':text})
out=root/'docs/central/index.html'
notes,edits={},{}
if out.exists():
    previous=out.read_text()
    match=re.search(r'<script type="application/json" id="data">(.*?)</script>',previous,re.S)
    if not match:raise SystemExit('Arquivo existente sem dados reconhecíveis; atualização interrompida para preservar anotações.')
    state=json.loads(match.group(1));notes=state.get('notes',{});edits=state.get('edits',{})
    from datetime import datetime
    backup=root/'artifacts/central'
    backup.mkdir(parents=True,exist_ok=True)
    (backup/('central-'+datetime.now().strftime('%Y%m%dT%H%M%S%f')+'.html')).write_text(previous)
html=r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Join Network · Central do projeto</title><style>
:root{--ink:#173b49;--muted:#637982;--green:#167760;--line:#dce5e6;--paper:#f4f7f6}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,textarea{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #d0a048;outline-offset:3px}.layout{display:grid;grid-template-columns:290px minmax(0,1fr);min-height:100vh}aside{background:#103745;color:white;padding:28px 20px;height:100vh;position:sticky;top:0;display:flex;flex-direction:column}.brand{font-weight:850;letter-spacing:-.5px;font-size:21px}.brand span{color:#9bdbc7}.tag{color:#b6d3d9;font-size:12px;margin:5px 0 25px}.search{width:100%;padding:12px;border:1px solid #496570;border-radius:9px;background:#1d4554;color:white;margin-bottom:18px}.search::placeholder{color:#bbd1d7}nav{overflow:auto;flex:1}nav h3{font-size:10px;text-transform:uppercase;letter-spacing:1.5px;color:#9dbac3;margin:22px 10px 8px}nav button{display:block;width:100%;text-align:left;border:0;background:none;color:#cfe0e4;padding:10px;border-radius:7px;font-size:12px;line-height:1.45;margin:3px 0}nav button.active{background:#d8efe7;color:#153f34;font-weight:700}nav button:hover{background:#2b5360;color:white}.side-foot{font-size:11px;color:#b9cdd3;padding-top:20px;border-top:1px solid #365460;margin-top:15px}main{padding:40px clamp(18px,4vw,64px);max-width:1280px;width:100%;margin:auto}.top{display:flex;justify-content:space-between;gap:16px;align-items:center}.eyebrow{font-size:11px;font-weight:750;letter-spacing:1.8px;text-transform:uppercase;color:var(--green)}.tools{display:flex;gap:8px;flex-wrap:wrap}button.action{border:1px solid var(--line);background:white;border-radius:8px;padding:9px 13px;color:var(--ink);font-size:12px;font-weight:600}.action.primary{background:var(--green);color:white;border-color:var(--green)}h1{font-size:clamp(27px,3.5vw,43px);line-height:1.15;letter-spacing:-1.2px;margin:20px 0 12px}.lead{color:var(--muted);max-width:760px}.status{font-size:12px;color:var(--green);min-height:22px}.meta{font-size:12px;color:var(--muted);margin:10px 0 25px}.card{background:white;border:1px solid var(--line);border-radius:14px;padding:clamp(18px,3vw,35px);margin:22px 0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.cards .card{margin:10px 0;padding:20px}.metric{font-size:27px;font-weight:750;display:block}.badge{display:inline-block;background:#e7f4ee;color:#15624c;padding:4px 9px;border-radius:20px;font-size:11px;font-weight:650}.note{border-left:3px solid #c6a963;background:#fbf5e8;padding:15px 20px;font-size:13px;margin:20px 0}.body h1{font-size:29px;letter-spacing:-.6px}.body h2{font-size:23px;margin-top:32px;line-height:1.25}.body h3{font-size:18px;margin-top:25px}.body h4{font-size:16px}.body p{margin:12px 0}.body a,a{color:var(--green)}.body ul,.body ol{padding-left:24px}.body li{margin:7px 0}.body pre{background:#112f3b;color:#d5e9e8;padding:20px;border-radius:10px;overflow:auto;font-size:12px}.body code{font:12px/1.6 ui-monospace,SFMono-Regular,monospace;overflow-wrap:anywhere}.body blockquote{border-left:3px solid #9ec8bb;margin:18px 0;padding:5px 20px;background:#f1f7f4}.table-wrap{overflow:auto}.body table{width:100%;border-collapse:collapse;font-size:13px}.body td,.body th{padding:11px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}.body th{background:#edf4f3}.body hr{border:0;border-top:1px solid var(--line);margin:25px 0}.notes label{font-size:14px;font-weight:700;display:block;margin-bottom:10px}textarea{width:100%;min-height:140px;border:1px solid #afc6c7;padding:14px;border-radius:8px;background:#fcfdfd;color:var(--ink);resize:vertical}.notes small{display:block;color:var(--muted);margin-top:9px}.edit-area{min-height:400px;font:13px/1.6 ui-monospace,monospace}.edit-bar{display:flex;gap:8px;margin-top:10px}.toc{display:flex;flex-wrap:wrap;gap:8px;margin:15px 0}.toc a{font-size:11px;background:#edf4f3;border-radius:6px;padding:5px 9px;text-decoration:none}footer{font-size:12px;color:var(--muted);margin-top:35px;border-top:1px solid var(--line);padding-top:20px}[hidden]{display:none!important}#empty{font-size:13px;color:#d3e5e8;padding:15px}#home ul{padding-left:20px}#home li{margin:8px 0}@media(max-width:800px){.layout{grid-template-columns:1fr}aside{position:relative;height:auto;padding:20px}nav{max-height:230px}.tag{margin-bottom:15px}.side-foot{display:none}.top{align-items:flex-start;flex-direction:column}main{padding:25px 16px}.cards{grid-template-columns:1fr}.cards .card{margin:0}h1{font-size:30px}.tools{gap:6px}}@media print{aside,.tools,.edit-bar,#editor,.notes small{display:none!important}.layout{display:block}main{max-width:none;padding:0}.card{border:0;padding:0}.body pre{white-space:pre-wrap}.body table{font-size:10px}.notes textarea{border:0;min-height:50px}.print-note{display:block!important;white-space:pre-wrap}.notes textarea{display:none}body{background:white;font-size:12px}.top{display:none}@page{margin:16mm}}
</style></head><body><div class="layout"><aside><div class="brand">JOIN<span>NETWORK</span></div><div class="tag">Central pessoal do projeto · 13/09/2026</div><label for="search" class="tag">Buscar em todos os documentos</label><input id="search" class="search" type="search" placeholder="Ex.: domínio, backup, vendas"><nav id="nav" aria-label="Documentação"></nav><p id="empty" hidden>Nenhum documento encontrado.</p><div class="side-foot">Arquivo pessoal, fora do Git.<br>Funciona sem internet.</div></aside><main><div class="top"><span class="eyebrow">Conhecimento e decisões</span><div class="tools"><button class="action" id="edit" hidden>Editar documento</button><button class="action" id="print">Imprimir</button><button class="action primary" id="download">Baixar HTML atualizado</button></div></div><div id="status" class="status" role="status"></div><div id="home"><h1>O projeto inteiro.<br>Um lugar para continuar.</h1><p class="lead">Consulta, planejamento e anotações reunidos. Use a busca ou escolha um documento no menu. Você pode editar uma cópia do conteúdo aqui e baixar o HTML com suas alterações.</p><div class="cards"><div class="card"><span class="metric" id="count"></span>documentos incorporados</div><div class="card"><span class="metric">ITUPEVA</span>filial piloto atual</div><div class="card"><span class="metric">SaaS</span>planejamento futuro registrado</div></div><div class="card"><span class="badge">Etapa atual · 5 de 7</span><h2>Homologação dos indicadores</h2><p>Importação ✓ → Painel ✓ → Publicação ✓ → Correções ✓ → <strong>Homologação (agora)</strong> → Expansão → SaaS</p><p>Login e movimentações mobile, fotos e dados do cliente corrigidos e verificados no domínio. Próximo passo: conferir os totais com o ERP junto de Maylon.</p></div><div class="card"><span class="badge">Estado atual · 13/09/2026</span><h2>Piloto publicado na Locaweb</h2><p><a href="https://aeropostale.joinnetwork.com.br" target="_blank" rel="noopener">aeropostale.joinnetwork.com.br</a></p><ul><li>HTTPS, login, indicadores e restrições de acesso verificados.</li><li>Banco migrado: 3.991 operações, 9.541 itens e 75 cancelamentos na conferência inicial.</li><li>Sincronização remota ativa; worker local desativado.</li><li>Backup diário configurado. Retenção e cópia externa recorrente ainda a definir.</li><li>Próximas decisões: homologação dos números, agrupamento de filiais e permissões.</li></ul></div><div class="note"><strong>Como ler os registros:</strong> os documentos contêm etapas históricas preservadas. Priorize as atualizações mais recentes no início dos arquivos. A expansão para dez clientes e a automação SaaS são propostas futuras.</div><div class="card"><h2>Seu espaço de trabalho</h2><p>As edições ficam nesta central e, quando permitido, no armazenamento deste navegador. Elas não alteram os arquivos Markdown nem o sistema publicado.</p><p><strong>Para guardar ou compartilhar:</strong> use “Baixar HTML atualizado”. A cópia inclui todos os documentos, suas edições e anotações. O arquivo pode conter informações internas do projeto.</p></div></div><div id="document" hidden><h1 id="title"></h1><div id="meta" class="meta"></div><div id="toc" class="toc"></div><div class="card body" id="body"></div><div id="editor" class="card" hidden><label for="source">Editar o texto Markdown desta cópia</label><textarea class="edit-area" id="source"></textarea><div class="edit-bar"><button class="action primary" id="apply">Aplicar edição</button><button class="action" id="cancel">Cancelar</button></div></div></div><div class="card notes"><label for="notes">Anotações e novos dados <span id="note-context">· visão geral</span></label><textarea id="notes" placeholder="Registre decisões, dúvidas e próximos passos…"></textarea><div id="print-note" class="print-note" hidden></div><small>Salvamento local quando disponível. Baixe uma cópia atualizada antes de fechar ou trocar de computador.</small></div><footer>Central consolidada a partir dos Markdown do projeto. Os originais foram preservados. Arquivo gerado em 13/09/2026 e ignorado pelo Git.</footer></main></div><script type="application/json" id="data">DATA_PLACEHOLDER</script><script>
const state=JSON.parse(document.getElementById('data').textContent);const baseDocs=state.docs;let current='home';const $=id=>document.getElementById(id);const storageKey='joinnetwork-central-v1';
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved){state.notes={...state.notes,...saved.notes};state.edits={...state.edits,...saved.edits};}}catch{}
const escape=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
function inline(s){const tokens=[];s=s.replace(/`([^`]+)`/g,(_,v)=>{tokens.push('<code>'+escape(v)+'</code>');return '\u0001'+(tokens.length-1)+'\u0001';});s=escape(s);s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,t,u)=>{if(/^(https?:|mailto:)/.test(u))return '<a href="'+u+'" target="_blank" rel="noopener">'+t+'</a>';if(!/^[\w.\-/]+(?:#[\w-]+)?$/.test(u))return t;return '<a href="#" data-local="'+u+'">'+t+'</a>';});s=s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');return s.replace(/\u0001(\d+)\u0001/g,(_,i)=>tokens[Number(i)]);}
function render(text){const lines=text.split('\n');let out='',list='',code=null,paragraph=[];const flush=()=>{if(paragraph.length){out+='<p>'+inline(paragraph.join(' '))+'</p>';paragraph=[];}if(list){out+='</'+list+'>';list='';}};for(let i=0;i<lines.length;i++){const l=lines[i];if(/^\s*```/.test(l)){flush();if(code!==null){out+='<pre><code>'+escape(code.join('\n'))+'</code></pre>';code=null;}else code=[];continue;}if(code!==null){code.push(l);continue;}if(!l.trim()){flush();continue;}const h=/^(#{1,6})\s+(.+)$/.exec(l);if(h){flush();out+='<h'+h[1].length+'>'+inline(h[2])+'</h'+h[1].length+'>';continue;}if(/^\s*\|/.test(l)&&i+1<lines.length&&/^\s*\|?[\s:|-]+\|[\s:|-]*$/.test(lines[i+1])){flush();const cells=x=>x.trim().replace(/^\||\|$/g,'').split('|').map(c=>c.trim());out+='<div class="table-wrap"><table><thead><tr>'+cells(l).map(c=>'<th>'+inline(c)+'</th>').join('')+'</tr></thead><tbody>';i++;while(i+1<lines.length&&/^\s*\|/.test(lines[i+1])){i++;out+='<tr>'+cells(lines[i]).map(c=>'<td>'+inline(c)+'</td>').join('')+'</tr>';}out+='</tbody></table></div>';continue;}const li=/^\s*(?:[-*]|\d+\.)\s+(.+)$/.exec(l);if(li){if(paragraph.length){out+='<p>'+inline(paragraph.join(' '))+'</p>';paragraph=[];}const type=/^\s*\d/.test(l)?'ol':'ul';if(list!==type){if(list)out+='</'+list+'>';list=type;out+='<'+list+'>';}out+='<li>'+inline(li[1]).replace(/^\[x\]/i,'✓').replace(/^\[ \]/,'□')+'</li>';continue;}if(/^>/.test(l)){flush();out+='<blockquote>'+inline(l.replace(/^>\s?/,''))+'</blockquote>';continue;}if(/^\s*---+\s*$/.test(l)){flush();out+='<hr>';continue;}if(list){out+='</'+list+'>';list='';}paragraph.push(l);}flush();if(code!==null)out+='<pre><code>'+escape(code.join('\n'))+'</code></pre>';return out;}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({notes:state.notes,edits:state.edits}));$('status').textContent='Alterações salvas neste navegador. Baixe o HTML para guardar uma cópia.';}catch{$('status').textContent='Armazenamento local indisponível. Baixe o HTML para guardar as alterações.';}}
function navigation(){const q=$('search').value.trim().toLocaleLowerCase();$('nav').replaceChildren();const home=document.createElement('button');home.textContent='Visão geral e decisões';home.className=current==='home'?'active':'';home.onclick=()=>openDoc('home');$('nav').append(home);let matches=0;for(const group of [...new Set(baseDocs.map(d=>d.group))]){const docs=baseDocs.filter(d=>d.group===group&&(!q||(d.title+' '+d.id+' '+(state.edits[d.id]??d.text)).toLocaleLowerCase().includes(q)));if(!docs.length)continue;const heading=document.createElement('h3');heading.textContent=group;$('nav').append(heading);for(const doc of docs){matches++;const b=document.createElement('button');b.textContent=doc.title;b.title=doc.id;b.dataset.id=doc.id;if(current===doc.id)b.classList.add('active');b.onclick=()=>openDoc(doc.id);$('nav').append(b);}}$('empty').hidden=matches!==0;}
function openDoc(id){current=id;$('editor').hidden=true;$('body').hidden=false;$('home').hidden=id!=='home';$('document').hidden=id==='home';$('edit').hidden=id==='home';$('notes').value=state.notes[id]||'';const d=baseDocs.find(d=>d.id===id);$('note-context').textContent='· '+(d?d.title:'visão geral');if(d){$('title').textContent=d.title;$('meta').textContent=d.id+(state.edits[id]!==undefined?' · edição pessoal nesta central':' · conteúdo incorporado');$('body').innerHTML=render(state.edits[id]??d.text);$('toc').replaceChildren();$('body').querySelectorAll('h2,h3').forEach((h,i)=>{h.id='sec-'+i;const a=document.createElement('a');a.href='#'+h.id;a.textContent=h.textContent;$('toc').append(a);});}navigation();}
$('search').addEventListener('input',navigation);$('notes').addEventListener('input',()=>{state.notes[current]=$('notes').value;persist();});$('edit').onclick=()=>{const d=baseDocs.find(d=>d.id===current);$('source').value=state.edits[current]??d.text;$('body').hidden=true;$('editor').hidden=false;$('source').focus();};$('apply').onclick=()=>{state.edits[current]=$('source').value;persist();openDoc(current);};$('cancel').onclick=()=>openDoc(current);
$('body').addEventListener('click',e=>{const a=e.target.closest('a[data-local]');if(!a)return;e.preventDefault();const raw=a.dataset.local.split('#')[0];const parts=current.split('/').slice(0,-1);for(const part of raw.split('/')){if(part==='..')parts.pop();else if(part&&part!=='.')parts.push(part);}const found=baseDocs.find(d=>d.id===parts.join('/'));if(found)openDoc(found.id);else $('status').textContent='Referência a arquivo externo à central: '+parts.join('/');});
$('download').onclick=()=>{const clone=document.documentElement.cloneNode(true);clone.querySelector('#data').textContent=JSON.stringify(state).replace(/</g,'\\u003c');const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['<!doctype html>\n'+clone.outerHTML],{type:'text/html;charset=utf-8'}));a.href=url;a.download='central-joinnetwork-atualizada.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='HTML com documentos, edições e anotações gerado para download.';};
$('print').onclick=()=>window.print();window.addEventListener('beforeprint',()=>{$('print-note').textContent=state.notes[current]||'Sem anotações.';});$('count').textContent=baseDocs.length;openDoc('home');
</script></body></html>'''
# JSON must stay inert even when source documents contain HTML/script fragments.
html=html.replace('DATA_PLACEHOLDER',json.dumps({'docs':docs,'notes':notes,'edits':edits},ensure_ascii=False).replace('<','\\u003c'))
out.parent.mkdir(parents=True,exist_ok=True);out.write_text(html)
print(f'{len(docs)} documentos incorporados em {out.relative_to(root)}')
